="#ef4444" strokeWidth={2} strokeDasharray="5 5" dot={false} name="추세선" /&gt; &lt;/BarChart&gt; &lt;/ResponsiveContainer&gt; {/* 통계 정보 */} &lt;div className="text-sm text-gray-600 text-center"&gt; 표시된 마켓: {chartData.length}개 / 전체: {data.length}개 &lt;/div&gt; &lt;/div&gt; );
}
핵심 구현 포인트
useMemo: displayCount나 data 변경 시에만 재계산
정렬: sort((a, b) =&gt; b.trend_weight - a.trend_weight) - 내림차순
