src/components/TrendScatterPlot.tsximport { useMemo } from 'react';
import { ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Line,
} from 'recharts';
import { calculateLinearRegression, getTrendLinePoints } from '../utils/linearRegression';
import type { MarketData } from '../types'; interface Props { data: MarketData[]; selectedMarkets?: string[]; onMarketClick?: (marketName: string) =&gt; void;
} export function TrendScatterPlot({ data, selectedMarkets = [], onMarketClick }: Props) { const { scatterData, trendLineData } = useMemo(() =&gt; { // Scatter 데이터 변환 const scatterData = data.map((item) =&gt; ({ x: item.trend_weight, y: item.last_high_price, market_name: item.market_name, isSelected: selectedMarkets.includes(item.market_name), })); // 선형 회귀 계산 const regressionData = data.map((item) =&gt; ({ x: item.trend_weight, y: item.last_high_price, })); const { slope, intercept } = calculateLinearRegression(regressionData); const trendLineData = getTrendLinePoints(regressionData, slope, intercept); return { scatterData, trendLineData }; }, [data, selectedMarkets]); const handleClick = (data: any) =&gt; { if (onMarketClick &amp;&amp; data &amp;&amp; data.market_name) { onMarketClick(data.market_name); } }; return ( &lt;ResponsiveContainer width="100%" height={500}&gt; &lt;ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }} &gt; &lt;CartesianGrid strokeDasharray="3 3" /&gt; &lt;XAxis type="number" dataKey="x" name="트렌드 가중치" label={{ value: '트렌드 가중치', position: 'insideBottom', offset: -10 }} /&gt; &lt;YAxis type="number" dataKey="y" name="최고가" label={{ value: '최고가 (원)', angle: -90, position: 'insideLeft' }} /&gt; &lt;Tooltip cursor={{ strokeDasharray: '3 3' }} content={({ payload }) =&gt; { if (!payload || payload.length === 0) return null; const data = payload[0].payload; return ( &lt;div className="bg-white p-3 border border-gray-300 rounded shadow-lg"&gt; &lt;p className="font-bold text-gray-900"&gt;{data.market_name}&lt;/p&gt; &lt;p className="text-sm text-gray-600"&gt; 트렌드: {data.x.toFixed(6)} &lt;/p&gt; &lt;p className="text-sm text-gray-600"&gt; 가격: {data.y.toLocaleString()}원 &lt;/p&gt; &lt;/div&gt; ); }} /&gt; &lt;Legend /&gt; {/* 추세선 */} &lt;Line type="monotone" data={trendLineData} dataKey="y" stroke="#ef4444" strokeWidth={2} strokeDasharray="5 5" dot={false} name="추세선" /&gt; {/* Scatter 점들 */} &lt;Scatter name="마켓" data={scatterData} fill="#3b82f6" onClick={handleClick} shape={(props: any) =&gt; { const { cx, cy, payload } = props; const isSelected = payload.isSelected; return ( &lt;circle cx={cx} cy={cy} r={isSelected ? 8 : 5} fill={isSelected ? '#ef4444' : '#3b82f6'} stroke={isSelected ? '#dc2626' : '#2563eb'} strokeWidth={2} style={{ cursor: 'pointer' }} /&gt; ); }} /&gt; &lt;/ScatterChart&gt; &lt;/ResponsiveContainer&gt; );
}
핵심 포인트
Custom Shape: 선택된 마켓은 크기/색상 변경
onClick 핸들러: 클릭 시 부모 컴포넌트에 알림
Custom Tooltip: 마켓명과 정확한 값 표시
