src/types/index.tsexport interface FilterOptions { trendRange: [number, number]; // [최소, 최대] priceRange: [number, number]; // [최소, 최대] searchText: string; // 검색어 sortBy: 'trend' | 'price' | 'name'; // 정렬 기준 sortOrder: 'asc' | 'desc'; // 정렬 순서
} export interface FilterPreset { id: string; name: string; filters: FilterOptions; createdAt: string;
}
타입 설계 특징
trendRange, priceRange: 튜플 타입으로 최소/최대값 표현
