src/hooks/useFilter.tsexport function useFilter(data: MarketData[]) { const [filters, setFilters] = useState&lt;FilterOptions&gt;(DEFAULT_FILTERS); // 데이터의 최소/최대값 자동 계산 const dataRange = useMemo(() =&gt; { if (!data || data.length === 0) { return { minTrend: 0, maxTrend: 1, minPrice: 0, maxPrice: 100000000 }; } const trends = data.map((d) =&gt; d.trend_weight); const prices = data.map((d) =&gt; d.last_high_price); return { minTrend: Math.min(...trends), maxTrend: Math.max(...trends), minPrice: Math.min(...prices), maxPrice: Math.max(...prices), }; }, [data]); // URL 쿼리 파라미터에서 필터 초기화 useEffect(() =&gt; { const params = new URLSearchParams(window.location.search); const urlFilters: FilterOptions = { trendRange: [ params.get('trendMin') ? parseFloat(params.get('trendMin')!) : dataRange.minTrend, params.get('trendMax') ? parseFloat(params.get('trendMax')!) : dataRange.maxTrend, ], priceRange: [ params.get('priceMin') ? parseFloat(params.get('priceMin')!) : dataRange.minPrice, params.get('priceMax') ? parseFloat(params.get('priceMax')!) : dataRange.maxPrice, ], searchText: params.get('search') || '', sortBy: (params.get('sortBy') as FilterOptions['sortBy']) || 'trend', sortOrder: (params.get('sortOrder') as FilterOptions['sortOrder']) || 'desc', }; setFilters(urlFilters); }, [dataRange]); // 필터 변경 시 URL 자동 업데이트 useEffect(() =&gt; { const params = new URLSearchParams(); // 기본값과 다를 때만 URL에 추가 (깔끔한 URL 유지) if (filters.trendRange[0] !== dataRange.minTrend) { params.set('trendMin', filters.trendRange[0].toString()); } if (filters.trendRange[1] !== dataRange.maxTrend) { params.set('trendMax', filters.trendRange[1].toString()); } // ... 나머지 필터들도 동일 const newUrl = params.toString() ? `${window.location.pathname}?${params.toString()}` : window.location.pathname; window.history.replaceState({}, '', newUrl); }, [filters, dataRange]); // 필터링 및 정렬된 데이터 const filteredData = useMemo(() =&gt; { if (!data) return []; let result = data.filter((item) =&gt; { // 트렌드 가중치 필터 if (item.trend_weight &lt; filters.trendRange[0] || item.trend_weight &gt; filters.trendRange[1]) { return false; } // 가격 범위 필터 if (item.last_high_price &lt; filters.priceRange[0] || item.last_high_price &gt; filters.priceRange[1]) { return false; } // 마켓명 검색 if (filters.searchText) { const searchLower = filters.searchText.toLowerCase(); if (!item.market_name.toLowerCase().includes(searchLower)) { return false; } } return true; }); // 정렬 result.sort((a, b) =&gt; { let compareValue = 0; switch (filters.sortBy) { case 'trend': compareValue = a.trend_weight - b.trend_weight; break; case 'price': compareValue = a.last_high_price - b.last_high_price; break; case 'name': compareValue = a.market_name.localeCompare(b.market_name); break; } return filters.sortOrder === 'asc' ? compareValue : -compareValue; }); return result; }, [data, filters]); return { filters, setFilters, filteredData, resetFilters, dataRange };
}
핵심 구현
데이터 범위 자동 계산: 실제 데이터의 최소/최대값을 useMemo로 계산
URL 동기화: 양방향 동기화 (URL → 필터, 필터 → URL)
필터링 로직: filter 메서드로 모든 조건 검증
정렬 로직: sort 메서드로 선택된 기준에 따라 정렬
src/hooks/useFilterPresets.tsconst STORAGE_KEY = 'filter_presets'; export function useFilterPresets() { const [presets, setPresets] = useState&lt;FilterPreset[]&gt;([]); // 로컬스토리지에서 프리셋 불러오기 useEffect(() =&gt; { const stored = localStorage.getItem(STORAGE_KEY); if (stored) { try { const parsed = JSON.parse(stored); setPresets(parsed); } catch (error) { console.error('프리셋 불러오기 오류:', error); } } }, []); // 프리셋 저장 const savePreset = (name: string, filters: FilterOptions) =&gt; { const newPreset: FilterPreset = { id: Date.now().toString(), name, filters, createdAt: new Date().toISOString(), }; const updatedPresets = [...presets, newPreset]; setPresets(updatedPresets); localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedPresets)); }; // 프리셋 삭제 const deletePreset = (id: string) =&gt; { const updatedPresets = presets.filter((p) =&gt; p.id !== id); setPresets(updatedPresets); localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedPresets)); }; // 프리셋 적용 const loadPreset = (id: string): FilterOptions | null =&gt; { const preset = presets.find((p) =&gt; p.id === id); return preset ? preset.filters : null; }; return { presets, savePreset, deletePreset, loadPreset };
}
